import base64
import io
from PIL import Image

KREDIYA_LOGO_B64 = ""
KREDIYA_LOGO_DATA_URI = "data:image/png;base64," + KREDIYA_LOGO_B64

def get_krediya_logo_bytes():
    return base64.b64decode(KREDIYA_LOGO_B64)

def get_krediya_logo_pil():
    return Image.open(io.BytesIO(get_krediya_logo_bytes()))
